/**
 * Auto-generated base64 encoded optimized Archi Draft certificate template image.
 */
export const CERTIFICATE_TEMPLATE_BASE64 =
  '';

export function getCertificateTemplateBytes(): Uint8Array {
  const binary = atob(CERTIFICATE_TEMPLATE_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}
